<script setup lang="ts">
import { computed,ref } from 'vue'
import { state,mutate } from '../state/household'
import { shell } from '../state/shell'
import { summary } from '../lib/selectors'
import { money,inputMoney,parseMoney } from '../lib/money'
import AppDialog from '../components/AppDialog.vue'
import { useSubmission } from '../lib/submission'
import FinancePanel from '../components/FinancePanel.vue'
const totals=computed(()=>summary(state.records,shell.month)),editing=ref(false),expected=ref('0.00'),values=ref<Record<string,string>>({})
const {saving,error,retryId,run}=useSubmission()
const budgetId=ref<string>(),budgetRevision=ref(0)
function edit(){budgetId.value=totals.value.budget?.id;budgetRevision.value=totals.value.budget?.revision??0;retryId.value='';values.value=Object.fromEntries(totals.value.rows.filter(x=>x.active||state.records.allocations.some(a=>!a.deleted&&a.budget_month_id===budgetId.value&&a.category_id===x.id)).map(x=>[x.id,inputMoney(x.allocated)]));expected.value=inputMoney(totals.value.expected);error.value='';editing.value=true}
async function save(){await run(()=>mutate('budget.set',{month:shell.month,expected_revision:budgetRevision.value,expected_income_minor:parseMoney(expected.value),allocations:Object.entries(values.value).map(([category_id,value])=>({category_id,amount_minor:parseMoney(value)}))},budgetId.value),()=>{editing.value=false})}
async function copy(){await run(()=>mutate('budget.set',{month:shell.month,allocations:null,expected_income_minor:0}),()=>{})}
</script>
<template><div class="page-heading"><div><h1>Budget</h1></div><button class="button primary" :disabled="!state.online" @click="edit">Edit budget</button></div><div class="toolbar"><label>Budget month<input v-model="shell.month" type="month" /></label><button v-if="!totals.budget" class="button" :disabled="!state.online||saving" @click="copy">Copy previous month’s plan</button></div><div v-if="error&&!editing" role="alert" class="notice error">{{error}}</div><div class="metrics"><section class="card"><small>Budgeted</small><strong class="metric-value">{{money(totals.allocated)}}</strong></section><section class="card"><small>Spent</small><strong class="metric-value">{{money(totals.spent)}}</strong></section><section class="card sage"><small>Unbudgeted income</small><strong class="metric-value">{{money(totals.expected-totals.allocated)}}</strong></section></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Category</th><th class="right">Budgeted</th><th class="right">Actual</th><th class="right">Remaining</th></tr></thead><tbody><tr v-for="c in totals.rows.filter(x=>x.active||x.actual||x.allocated)" :key="c.id"><td><strong>{{c.name}}</strong><small v-if="c.kind==='savings'" style="display:block">Net savings contribution</small><small v-if="!c.active"> · Archived</small></td><td class="right">{{money(c.allocated)}}</td><td class="right">{{money(c.actual)}}</td><td class="right" :class="{negative:c.remaining<0}">{{money(c.remaining)}}</td></tr></tbody></table></div></section><p class="text-small section-space">Personal subcategories share their parent budget. Unused budgets do not carry forward.</p><FinancePanel /><AppDialog v-if="editing" title="Edit budget" @close="editing=false"><form @submit.prevent="save"><div v-if="error" role="alert" class="notice error">{{error}}</div><fieldset :disabled="saving||!!retryId"><label>Expected income ($)<input v-model="expected" inputmode="decimal" required /></label><div v-for="c in totals.rows.filter(x=>x.id in values)" :key="c.id" class="allocation-row"><label :for="'allocation-'+c.id">{{c.name}}<span v-if="!c.active"> · Archived</span></label><input :disabled="!c.active" :id="'allocation-'+c.id" v-model="values[c.id]" inputmode="decimal" required /></div></fieldset><p class="text-small">Budgets may exceed expected income.</p><button class="button primary" :disabled="saving">{{saving?'Saving…':retryId?'Retry saved submission':'Save budget'}}</button></form></AppDialog></template>
